INSERT INTO rules (rule_name, drug_name, symptom, symptom_ml, severity, action_card, action_card_ml, active) VALUES
('Dosulepin Anticholinergic Alert', 'Dothiepin', 'dry mouth', 'ഉമിനീർ കുറവ്', 'low', 'Sip water frequently; use sugar-free gum; maintain oral hygiene', 'വായ വരണ്ടുപോകുന്നത് കുറയ്ക്കാൻ വെള്ളം ഇടയ്ക്കിടെ കുടിക്കുക, പഞ്ചസാര ഇല്ലാത്ത ച്യൂയിംഗ് ഗം ഉപയോഗിക്കുക, വായ ശുചിത്വം നല്ലതായി പാലിക്കുക.', TRUE),
('Dosulepin Arrhythmia Emergency', 'Dothiepin', 'irregular heartbeat +/ fainting +/ palpitation', 'ഹൃദയമിടിപ്പ് ക്രമക്കേട് ± ബോധംകെടുക', 'critical', 'Go to nearest hospital casualty immediately', 'ഉടൻ ആശുപത്രിയിൽ പോകുക.', TRUE),
('Dosulepin Constipation Alert', 'Dothiepin', 'constipation', 'മലബന്ധം', 'medium', 'Increase fibre/fluid diet; if >3 days, Visit doctor if persistent >3 days', 'കൂടുതൽ ദ്രാവകങ്ങൾ(വെള്ളം) കുടിക്കുക, ഫൈബർ(നാരുകൾ) ഉള്ള ഭക്ഷണം കഴിക്കുക. ലക്ഷണങ്ങൾ 3 ദിവസത്തിലധികം തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Agomelatine Liver Alert', 'Agomelatine', 'jaundice +/ dark urine', 'മഞ്ഞപ്പിത്തം ± ഇരുണ്ട മൂത്രം', 'high', 'Stop Agomelatine and contact your doctor immediately; liver function needs to be checked.', 'അഗോമെലാറ്റിൻ മരുന്ന് നിർത്തുക; ഉടൻ ഡോക്ടറെ ബന്ധപ്പെടുക; കരൾ പ്രവർത്തനം പരിശോധിക്കേണ്ടതാണ്', TRUE),
('Topiramate Oligohidrosis Alert', 'Topiramate', 'decreased sweating with overheating', 'വിയർപ്പ് കുറവ് +/ ശരീരചൂട് കൂടൽ', 'high', 'Stop exertion, cool the body, and consult doctor.', 'അധ്വാനം നിർത്തുക, ശരീരം തണുപ്പിക്കുക, ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Agomelatine Dizziness Alert', 'Agomelatine', 'dizziness', 'തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Topiramate Oligohidrosis Alert', 'Topiramate', 'decreased sweating with overheating', 'വിയർപ്പ് കുറവ് +/ ശരീരചൂട് കൂടൽ', 'high', 'Stop exertion, cool the body, and consult doctor.', 'അധ്വാനം നിർത്തുക, ശരീരം തണുപ്പിക്കുക, ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Dosulepin Sedation Rule', 'Dothiepin', 'sedation', 'പകൽ അമിത ഉറക്കം +/ മയക്കം +/ ക്ഷീണം', 'low', 'Avoid driving; take at bedtime; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed, if daytime drowsiness persisting, visit doctor', 'വണ്ടി ഓടിക്കൽ ഒഴിവാക്കുക; മരുന്ന് രാത്രി ഉറങ്ങാൻ മുമ്പ് കഴിക്കുക; പ്രത്യേകിച്ച് 50 വയസിന് മുകളിലുള്ളവർ കിടക്കയിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ വീഴ്ച ഒഴിവാക്കാൻ ആവശ്യമായ ജാഗ്രത പാലിക്കുക; പകൽ ഉറക്കം തുടർന്നാൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Amisulpride EPS Alert', 'Amisulpride', 'fever  +/ sweating +/ tremors +/ restlessness +/ muscle stiffness +/ confusion +/ diarrhoea', 'പനി ± വിയർപ്പ് ± വിറയൽ ± പിരുപിരുപ്പ് ± മാംസപേശി കാഠിന്യം ± ആശയക്കുഴപ്പം ± വയറിളക്കം', 'high', 'Stop Amisulpride drug, Visit doctor immediately', 'അമിസൾപ്രൈഡ് നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Amisulpride NMS Emergency', 'Amisulpride', 'fever  +/ sweating +/ tremors +/ restlessness +/ muscle stiffness +/ confusion +/ diarrhoea', 'പനി ± വിയർപ്പ് ± വിറയൽ ± പിരുപിരുപ്പ് ± മാംസപേശി കാഠിന്യം ± ആശയക്കുഴപ്പം ± വയറിളക്കം', 'critical', 'Stop Amisulpride drug, Visit doctor immediately', 'അമിസൾപ്രൈഡ് നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Dosulepin Tachycardia Alert', 'Dothiepin', 'palpitations', 'നെഞ്ചിടിപ്പ്', 'high', 'Visit doctor immediately; avoid exertion', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക. കുറയുന്നതുവരെ അധ്വാനം ഒഴിവാക്കുക.', TRUE),
('Dosulepin Urinary Retention Alert', 'Dothiepin', 'difficulty urinating', 'മൂത്രതടസ്സം', 'high', 'Visit doctor immediately; risk of urinary retention', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക. മൂത്രതടസ്സത്തിന്റെ സാധ്യതയുണ്ട്.', TRUE),
('Dosulepin Vision Blur Alert', 'Dothiepin', 'blurred vision', 'കാഴ്ച മങ്ങൽ', 'medium', 'Avoid driving; Visit doctor if persistent', 'വാഹനം ഓടിക്കുന്നത് ഒഴിവാക്കുക. ലക്ഷണങ്ങൾ മാറാതെ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Dosulepin Weight Gain Warning', 'Dothiepin', 'weight gain', 'ഭാരം കുറയൽ / ഭാരം കൂടൽ / ഭാരം മാറ്റം', 'low', 'Monitor weight weekly; diet modification and exercise', 'ഓരോ ആഴ്ചയും ശരീരഭാരം പരിശോധിക്കുക; ഭക്ഷണനിയന്ത്രണവും വ്യായാമവും പാലിക്കുക. ബുദ്ധിമുട്ട് ഉണ്ടാകുന്നുവെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Brexanolone Dizziness Rule', 'Brexanolone', 'dizziness', 'തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Agomelatine Fatigue Rule', 'Agomelatine', 'fatigue', 'ക്ഷീണം', 'low', 'Monitor; Visit doctor if marked or worsening', 'നിരീക്ഷിക്കുക; ലക്ഷണങ്ങൾ ശക്തമാകുകയോ മോശമാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Agomelatine GI Upset Rule', 'Agomelatine', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Agomelatine Headache Rule', 'Agomelatine', 'headache', 'തലവേദന', 'low', 'Monitor; simple analgesic if needed; Visit doctor if persistent; ensure adequate water intake', 'കൂടുതൽ വെള്ളം കുടിക്കുക; ആവശ്യമായാൽ ലളിതമായ വേദനാശമന മരുന്ന് (പാരാസിറ്റമോൾ) കഴിക്കാൻ പരിഗണിക്കുക; തുടർന്നും ഗുരുതരവുമെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Agomelatine LFT Rise Alert', 'Agomelatine', 'impaired liver function on lab report', 'ലാബ് റിപ്പോർട്ടിൽ കരളിന്റെ പ്രവർത്തനം കുറവായി കാണുക', 'high', 'Discuss with doctor; consider dose reduction or discontinuation', 'ഡോക്ടറുമായി ചർച്ച ചെയ്യുക; ഡോസ് കുറയ്ക്കുകയോ മരുന്ന് നിർത്തുകയോ ചെയ്യേണ്ടതായി വരാം.', TRUE),
('Aripiprazole EPS Alert', 'Aripiprazole', 'fever  +/ sweating +/ tremors +/ restlessness +/ muscle stiffness +/ confusion +/ diarrhoea', 'പനി ± വിയർപ്പ് ± വിറയൽ ± പിരുപിരുപ്പ് ± മാംസപേശി കാഠിന്യം ± ആശയക്കുഴപ്പം ± വയറിളക്കം', 'medium', 'Stop Aripiprazole; visit doctor immediately', 'അരിപിപ്രാസോൾ മരുന്ന് നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Agomelatine Sleep Disturbance', 'Agomelatine', 'vivid dreams +/ nightmares', 'അസ്വസ്ഥമാകുന്ന സ്വപ്നങ്ങൾ', 'medium', 'Stop Agomelatin; visit doctor immediately', 'അഗോമെലാറ്റിൻ മരുന്ന് നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Agomelatine Suicidal Thought Alert', 'Agomelatine', 'suicidal thoughts', 'ആത്മഹത്യാ ചിന്തകൾ', 'critical', 'Urgent psychiatric help or hospital assessment, do not stay alone', 'ഇത്തരം ചിന്തകൾ ഉണ്ടെങ്കിൽ ഉടൻ ഡോക്ടറെ കാണുക / അടുത്ത ആശുപത്രിയിൽ പോകുക. സഹായം തേടുന്നത് വളരെ പ്രധാനമാണ്. തനിച്ചിരിക്കുക ഒഴിവാക്കണം', TRUE),
('Alprazolam Cognitive Impairment Alert', 'Alprazolam', 'confusion +/ memory problems', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ ഓർമ്മക്കുറവ്', 'medium', 'Visit doctor immediately', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Alprazolam Dependence/Craving Alert', 'Alprazolam', 'strong desire to take extra tablets', 'കൂടുതൽ ഗുളികകൾ കഴിക്കാനുള്ള ശക്തമായ ആഗ്രഹം', 'high', 'Contact doctor immediately; dependence risk', 'ഉടൻ ഡോക്ടറെ ബന്ധപ്പെടുക; dependence risk', TRUE),
('Buspirone Dizziness Alert', 'Buspirone', 'dizziness', 'തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Alprazolam Rebound Anxiety Alert', 'Alprazolam', 'worse anxiety as dose wears off', 'ഉത്കണ്ഠ', 'high', 'Visit doctor; needs dose review and gradual taper', 'ഡോക്ടറെ സമീപിക്കുക; ഡോസ് റിവ്യൂ ചെയ്ത് പതുക്കെ കുറയ്ക്കണം', TRUE),
('Alprazolam Respiratory Depression Alert', 'Alprazolam', 'slow +/ difficult breathing ', 'മന്ദഗതിയിലുള്ള ശ്വാസം ± ശ്വാസം എടുക്കാൻ ബുദ്ധിമുട്ട്', 'critical', 'hospital immediately; life-threatening', 'ഉടൻ ആശുപത്രിയിൽ പോകുക.', TRUE),
('Alprazolam Sedation Rule', 'Alprazolam', 'sedation', 'പകൽ അമിത ഉറക്കം +/ മയക്കം +/ ക്ഷീണം', 'low', 'Avoid driving; take at bedtime; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed, if daytime drowsiness persisting, visit doctor', 'വണ്ടി ഓടിക്കൽ ഒഴിവാക്കുക; മരുന്ന് രാത്രി ഉറങ്ങാൻ മുമ്പ് കഴിക്കുക; പ്രത്യേകിച്ച് 50 വയസിന് മുകളിലുള്ളവർ കിടക്കയിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ വീഴ്ച ഒഴിവാക്കാൻ ആവശ്യമായ ജാഗ്രത പാലിക്കുക; പകൽ ഉറക്കം തുടർന്നാൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Alprazolam Withdrawal Seizure Emergency', 'Alprazolam', 'seizure after sudden stop +/ missed doses', 'മരുന്ന് പെട്ടെന്ന് നിർത്തിയതിനു ശേഷം ഫിറ്റ്സ്', 'critical', 'Go to hospital immediately; do not restart without doctor', 'ഉടൻ ആശുപത്രിയിൽ പോകുക; ഡോക്ടറുടെ നിർദേശം ഇല്ലാതെ മരുന്ന് വീണ്ടും ആരംഭിക്കരുത്.', TRUE),
