('Etoperidone Dizziness Alert', 'Etoperidone', 'dizziness', 'തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Bupropion + dextromethorphan Dry Mouth Rule', 'Bupropion + dextromethorphan (fixed combo)', 'dry mouth', 'ഉമിനീർ കുറവ്', 'low', 'Sip water frequently; use sugar-free gum; maintain oral hygiene', 'വായ വരണ്ടുപോകുന്നത് കുറയ്ക്കാൻ വെള്ളം ഇടയ്ക്കിടെ കുടിക്കുക, പഞ്ചസാര ഇല്ലാത്ത ച്യൂയിംഗ് ഗം ഉപയോഗിക്കുക, വായ ശുചിത്വം നല്ലതായി പാലിക്കുക.', TRUE),
('Bupropion + dextromethorphan Insomnia Alert', 'Bupropion + dextromethorphan (fixed combo)', 'insomnia', 'ഉറക്കമില്ലായ്മ', 'medium', 'Avoid evening dosing; sleep hygiene; Visit doctor if severe', 'മരുന്ന് രാവിലെ അല്ലെങ്കിൽ ദിവസം തുടങ്ങുമ്പോൾ തന്നെ കഴിക്കുക; വൈകുന്നേരം/രാത്രി ഡോസ് ഒഴിവാക്കുക; കഫീൻ (ചായ, കാപ്പി) കുറയ്ക്കുക; നല്ല ഉറക്കശീലങ്ങൾ പാലിക്കുക; ലക്ഷണങ്ങൾ കടുത്തതോ തുടർച്ചയായതോ ആണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Bupropion + dextromethorphan Mood Switch Alert', 'Bupropion + dextromethorphan (fixed combo)', 'overactivity/less need for sleep', 'ഉറക്കം കുറയുക ± ഊർജം കൂടുക', 'high', 'Visit doctor; possible hypomania/mania', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Bupropion + dextromethorphan Nausea Rule', 'Bupropion + dextromethorphan (fixed combo)', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Carbamazepine Rash Emergency', 'Carbamazepine', 'rash +/ blisters', 'തൊലിയിൽ ചുവന്ന പാട്± പുണ്ണുകൾ', 'critical', 'Stop Carbamazepine; hospital immediately (SJS/TEN risk)', 'കാർബമസപീൻ നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Carbamazepine Liver Alert', 'Carbamazepine', 'jaundice +/ dark urine', 'മഞ്ഞപ്പിത്തം ± ഇരുണ്ട മൂത്രം', 'high', 'Stop Carbamazepine and contact your doctor immediately; liver function needs to be checked.', 'കാർബമസെപിൻ മരുന്ന് നിർത്തുക; ഉടൻ ഡോക്ടറെ ബന്ധപ്പെടുക; കരൾ പ്രവർത്തനം പരിശോധിക്കേണ്ടതാണ്', TRUE),
('Bupropion + dextromethorphan Suicidal Thought Alert', 'Bupropion + dextromethorphan (fixed combo)', 'suicidal thoughts', 'ആത്മഹത്യാ ചിന്തകൾ', 'critical', 'Urgent psychiatric help or hospital assessment, do not stay alone', 'ഇത്തരം ചിന്തകൾ ഉണ്ടെങ്കിൽ ഉടൻ ഡോക്ടറെ കാണുക / അടുത്ത ആശുപത്രിയിൽ പോകുക. സഹായം തേടുന്നത് വളരെ പ്രധാനമാണ്. തനിച്ചിരിക്കുക ഒഴിവാക്കണം', TRUE),
('Buspirone Blurred Vision Alert', 'Buspirone', 'blurred vision', 'കാഴ്ച മങ്ങൽ', 'medium', 'Avoid driving; Visit doctor if persistent', 'വാഹനം ഓടിക്കുന്നത് ഒഴിവാക്കുക. ലക്ഷണങ്ങൾ മാറാതെ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Fluoxetine Dizziness Rule', 'Fluoxetine', 'dizziness', 'തലകറക്കം', 'low', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Buspirone Headache Rule', 'Buspirone', 'headache', 'തലവേദന', 'low', 'Monitor; simple analgesic if needed; Visit doctor if persistent; ensure adequate water intake', 'കൂടുതൽ വെള്ളം കുടിക്കുക; ആവശ്യമായാൽ ലളിതമായ വേദനാശമന മരുന്ന് (പാരാസിറ്റമോൾ) കഴിക്കാൻ പരിഗണിക്കുക; തുടർന്നും ഗുരുതരവുമെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Buspirone Lightheadedness', 'Buspirone', 'lightheadedness after dose', 'കുറഞ്ഞ രക്തസമ്മർദ്ദം ± തലചുറ്റൽ', 'low', 'Rise slowly; hydrate; Visit doctor if recurrent for adjusting dose', 'പതുക്കെ എഴുന്നേൽക്കുക; ജലാംശം നിലനിർത്തുക (ധാരാളം വെള്ളം കുടിക്കുക); ഇത് ആവർത്തിച്ചാൽ ഡോസ് ക്രമീകരിക്കാൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Buspirone Nausea Rule', 'Buspirone', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Armodafinil mood switch alert', 'Armodafinil', 'restlessness +/ increased energy +/ overtalkativeness +/ reduced sleep', 'പിരുപിരുപ്പ് ± ഊർജം കൂടുക ± അതിയായി സംസാരിക്കുക ± ഉറക്കം കുറയുക', 'Severe', 'Stop Armodafinil; visit doctor urgently', 'ആർമോഡാഫിനിൽ മരുന്ന് നിർത്തുക; അടിയന്തിരമായി ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Buspirone Palpitation Alert', 'Buspirone', 'palpitations', 'നെഞ്ചിടിപ്പ്', 'high', 'Visit doctor for evaluation', 'ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Clomipramine Serotonin Syndrome Alert', 'Clomipramine', 'fever +/ sweating +/ tremors +/ restlessness +/ muscle stiffness +/ confusion +/ diarrhoea', 'പനി ± വിയർപ്പ് ± വിറയൽ ± പിരുപിരുപ്പ് ± മാംസപേശി കാഠിന്യം ± ആശയക്കുഴപ്പം ± വയറിളക്കം', 'critical', 'Stop Clomipramine; visit doctor immediately', 'ക്ലോമിപ്രാമിൻ നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Clomipramine Seizure Emergency', 'Clomipramine', 'seizure', 'ഫിറ്റ്സ്', 'critical', 'Stop Clomipramine; visit doctor immediately', 'ക്ലോമിപ്രാമിൻ നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Carbamazepine Cardiac Alert', 'Carbamazepine', 'palpitations', 'നെഞ്ചിടിപ്പ്', 'high', 'Visit doctor', 'ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Hydroxyzine Dizziness Alert', 'Hydroxyzine', 'dizziness', 'തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Carbamazepine Drowsiness Rule', 'Carbamazepine', 'drowsiness', 'പകൽ അമിത ഉറക്കം +/ മയക്കം.', 'low', 'Avoid driving; take at bedtime; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed, if daytime drowsiness persisting, avoid alcohol; visit doctor', 'വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. മരുന്ന് രാത്രി ഉറങ്ങാൻ പോകുന്ന സമയത്ത് കഴിക്കുക. 50 വയസ്സിന് മുകളിലുള്ളവർ കിടക്കയിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക. പകൽ മയക്കം തുടരുകയാണെങ്കിൽ മദ്യപാനം ഉണ്ടെങ്കിൽ ഒഴിവാക്കുക, ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Carbamazepine GI Upset Rule', 'Carbamazepine', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Carbamazepine Hyponatraemia Alert', 'Carbamazepine', 'confusion+/ headache', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ തലവേദന', 'high', 'Checking sodium may be needed; Visit doctor immediately; Avoid driving; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed.', 'രക്തത്തിലെ സോഡിയം പരിശോധിക്കുക. ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Chlordiazepoxide Jaundice Alert', 'Chlordiazepoxide', 'yellowing of eyes/skin', 'കണ്ണുകളോ ചർമ്മമോ മഞ്ഞനിറമാകുക', 'high', 'Stop Chlordiazepoxide and contact your doctor immediately; liver function needs to be checked.', 'ക്ലോർഡയാസെപോക്സൈഡ് മരുന്ന് നിർത്തുക; ഉടൻ ഡോക്ടറെ ബന്ധപ്പെടുക; കരൾ പ്രവർത്തനം പരിശോധിക്കേണ്ടതായി വരും', TRUE),
('Chlorpromazine NMS Emergency', 'Chlorpromazine', 'fever +/ sweating +/ tremors +/ restlessness +/ muscle stiffness +/ confusion +/ diarrhoea', 'പനി ± വിയർപ്പ് ± വിറയൽ ± പിരുപിരുപ്പ് ± മാംസപേശി കാഠിന്യം ± ആശയക്കുഴപ്പം ± വയറിളക്കം', 'critical', 'Stop Chlorpromazine; visit doctor immediately', 'ക്ലോർപ്രോമസിൻ നിർത്തുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
