('Sertraline Headache Rule', 'Sertraline', 'headache', 'തലവേദന', 'low', 'Monitor; simple analgesic if needed; Visit doctor if persistent; ensure adequate water intake', 'കൂടുതൽ വെള്ളം കുടിക്കുക; ആവശ്യമായാൽ ലളിതമായ വേദനാശമന മരുന്ന് (പാരാസിറ്റമോൾ) കഴിക്കാൻ പരിഗണിക്കുക; തുടർന്നും ഗുരുതരവുമെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Sertraline Hyponatraemia Alert', 'Sertraline', 'confusion/drowsiness', 'മന്ദത+/ അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ അധികം ഉറക്കം തോന്നൽ', 'high', 'Checking sodium may be needed; Visit doctor immediately; Avoid driving; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed.', 'സോഡിയം ലെവൽ പരിശോധിക്കേണ്ടതായി വരാം. ഉടൻ ഡോക്ടറെ സമീപിക്കുക. വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക.', TRUE),
('Sertraline Nausea Rule', 'Sertraline', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; common early effect; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Diazepam Paradoxical Agitation', 'Diazepam', 'irritability +/ aggression', 'ഇടയ്ക്കിടെ ദേഷ്യം', 'high', 'Visit doctor; Diazepam may need to be stopped', 'ഡോക്ടറെ സമീപിക്കുക; ഡയസിപാം നിർത്തേണ്ടതായി വരാം.', TRUE),
('Sertraline Sexual Dysfunction Alert', 'Sertraline', 'libido issues', 'ലൈംഗിക ആഗ്രഹം കുറയുക / ഉദ്ധാരണക്കുറവ്', 'medium', 'Discuss if distressing', 'ബുദ്ധിമുട്ടുണ്ടാക്കുന്നുവെങ്കിൽ ഡോക്ടറുമായി ചർച്ച ചെയ്യുക; ഡോസ് മാറ്റം ആവശ്യമാകാം.', TRUE),
('Valproate Encephalopathy Alert', 'Sodium Valproate', 'confusion +/ drowsiness', 'മന്ദത+/ അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ അതിയായ ഉറക്കം തോന്നൽ', 'high', 'Checking sodium and ammonia levels may be needed; Visit doctor immediately; Avoid driving; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed.', 'അമോണിയ ലെവൽ, സോഡിയം ലെവൽ പരിശോധിക്കേണ്ടതായി വരാം. ഉടൻ ഡോക്ടറെ സമീപിക്കുക. വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക.', TRUE),
('Valproate GI Upset Rule', 'Sodium Valproate', 'nausea +/ stomach discomfort', 'ഓക്കാനം ± വയറ്റിൽ അസ്വസ്ഥത', 'low', 'Take with food; common early effect; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Valproate Hair Loss Rule', 'Sodium Valproate', 'hair thinning', 'മുടികൊഴിച്ചിൽ', 'low', 'Usually reversible; Visit doctor if severe', 'പൊതുവെ ഇത് മാറും; വളരെ ബുദ്ധിമുട്ടുണ്ടെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക', TRUE),
('Dosulepin Rash Alert', 'Dosulepin', 'rash', 'തൊലിയിൽ ചുവന്ന പാട്', 'medium', 'Stop Dosulepin and Visit doctor; assess allergy', 'ഡോസുലെപിൻ നിർത്തുക; അലർജി ഉണ്ടോയെന്ന് വിലയിരുത്താൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Valproate Pancreatitis Emergency', 'Sodium Valproate', 'severe abdominal pain + vomiting', 'കഠിനമായ വയറുവേദന ± ഛർദ്ദി', 'critical', 'Go to hospital immediately', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Valproate Rash Alert', 'Sodium Valproate', 'rash +/ skin reaction', 'തൊലിയിൽ ചുവന്ന പാട് ± ചൊറിച്ചിൽ', 'medium', 'Visit doctor; may need drug change', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Valproate Suicidal Thought Alert', 'Sodium Valproate', 'suicidal thoughts', 'ആത്മഹത്യാ ചിന്തകൾ', 'critical', 'Urgent psychiatric help or hospital assessment, do not stay alone', 'ഇത്തരം ചിന്തകൾ ഉണ്ടെങ്കിൽ ഉടൻ ഡോക്ടറെ കാണുക / അടുത്ത ആശുപത്രിയിൽ പോകുക. സഹായം തേടുന്നത് വളരെ പ്രധാനമാണ്. തനിച്ചിരിക്കുക ഒഴിവാക്കണം', TRUE),
('Valproate Thrombocytopenia Alert', 'Sodium Valproate', 'easy bruising +/ nosebleeds', 'നീലപ്പാടുകൾ വരുക +/ മൂക്കിൽ നിന്ന് രക്തസ്രാവം', 'high', 'Visit a doctor immediately to evaluate for possible bleeding (GI or otherwise), check platelet count, review drug interactions, and avoid NSAIDs.', 'രക്തസ്രാവം (ആന്തരാവയവങ്ങളിലോ മറ്റിടങ്ങളിലോ) ഉണ്ടോ എന്ന് പരിശോധിക്കാനും, പ്ലേറ്റ്‌ലെറ്റ് കൗണ്ട് പരിശോധിക്കാനും, മരുന്നുകളുടെ ഇന്ററാക്ഷൻ പരിശോധിക്കാനും, NSAID ഒഴിവാക്കാനും ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Valproate Tremor Alert', 'Sodium Valproate', 'tremor', 'വിറയൽ', 'medium', 'Visit doctor; may need dose adjustment', 'ഡോക്ടറെ സമീപിക്കുക; ഡോസ് മാറ്റo ആവശ്യമാകാം.', TRUE),
('Valproate Weight Gain Alert', 'Sodium Valproate', 'weight gain', 'ഭാരം കുറയൽ / ഭാരം കൂടൽ / ഭാരം മാറ്റം', 'medium', 'Monitor weight weekly; diet modification and exercise', 'ഓരോ ആഴ്ചയും ശരീരഭാരം പരിശോധിക്കുക; ഭക്ഷണനിയന്ത്രണവും വ്യായാമവും പാലിക്കുക. ബുദ്ധിമുട്ട് ഉണ്ടാകുന്നുവെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Thioridazine Anticholinergic Alert', 'Thioridazine', 'dry mouth/blurred vision', 'ഉമിനീർ കുറവ്+/ കാഴ്ച മങ്ങൽ', 'medium', 'Sip water frequently; use sugar-free gum; maintain oral hygiene', 'കാഴ്ച മങ്ങുന്നതുള്ളതിനാൽ വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക. വായ വരണ്ടുപോകുന്നത് കുറയ്ക്കാൻ വെള്ളം ഇടയ്ക്കിടെ കുടിക്കുക, പഞ്ചസാര ഇല്ലാത്ത ച്യൂയിംഗ് ഗം ഉപയോഗിക്കുക, വായ ശുചിത്വം നല്ലതായി പാലിക്കുക.', TRUE),
('Thioridazine Dystonia Emergency', 'Thioridazine', 'severe neck +/ jaw muscle spasm +/ eyes rolling upwards', 'കഴുത്തിലും / താടിയിലും കഠിനമായ പേശിവലിവ് ± കണ്ണുകൾ മുകളിലേക്ക് തിരിയുന്നു', 'critical', 'Go to hospital immediately for anticholinergic therapy', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Thioridazine EPS Alert', 'Thioridazine', 'stiffness/tremor', 'പേശി മുറുക്കം +/ വിറയൽ', 'high', 'Visit doctor; adjust dose or add antiparkinsonian', 'ഡോക്ടറെ കാണുക; ഡോസ് മാറ്റo ആവശ്യമാകാം', TRUE),
('Dosulepin Glaucoma Emergency', 'Dosulepin', 'severe eye pain/vision loss', 'കഠിനമായ കണ്ണുവേദന +/ കാഴ്ച മങ്ങൽ', 'critical', 'Urgent ophthalmology hospital; stop Dosulepin immediately', 'അടിയന്തിരമായി കണ്ണ് വിഭാഗമുള്ള ആശുപത്രിയിൽ പോകുക; ഡോസുലെപിൻ ഉടൻ നിർത്തുക', TRUE),
('Quetiapine Orthostasis Warning', 'Quetiapine', 'dizziness on standing', 'എഴുന്നേൽക്കുമ്പോൾ തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Thioridazine QT Prolongation Emergency', 'Thioridazine', 'syncope +/ irregular heartbeat', 'ബോധക്ഷയം (കുഴഞ്ഞുവീഴൽ) ± ഹൃദയമിടിപ്പ് ക്രമക്കേട്', 'critical', 'Go to hospital immediately; risk of serious arrhythmia', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Thioridazine Retinal Toxicity Alert', 'Thioridazine', 'visual blurring +/ colour vision change', 'കാഴ്ച മങ്ങൽ ± നിറങ്ങൾ തിരിച്ചറിയുന്നതിൽ മാറ്റം', 'high', 'Visit doctor immediately; ophthalmology review', 'ഉടൻ ഡോക്ടറെ കാണുക; കണ്ണുഡോക്ടറുടെ (ഓഫ്താൽമോളജി) പരിശോധന ആവശ്യമാണ്', TRUE),
('Thioridazine Sedation Rule', 'Thioridazine', 'sedation', 'പകൽ അമിത ഉറക്കം +/ മയക്കം +/ ക്ഷീണം', 'low', 'Avoid driving; take at bedtime; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed, if daytime drowsiness persisting, visit doctor', 'വണ്ടി ഓടിക്കൽ ഒഴിവാക്കുക; മരുന്ന് രാത്രി ഉറങ്ങാൻ മുമ്പ് കഴിക്കുക; പ്രത്യേകിച്ച് 50 വയസിന് മുകളിലുള്ളവർ കിടക്കയിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ വീഴ്ച ഒഴിവാക്കാൻ ആവശ്യമായ ജാഗ്രത പാലിക്കുക; പകൽ ഉറക്കം തുടർന്നാൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Trifluperidol Akathisia Alert', 'Trifluperidol', 'restlessness +/ unable to sit still', 'പിരുപിരുപ്പ് ± ഒരിടത്ത് ഇരിക്കാൻ കഴിയാത്തത്', 'high', 'Visit doctor immediately; dose review', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക; ഡോസ് മാറ്റമോ മരുന്ന് മാറ്റമോ ആവശ്യമാകാം.', TRUE),
('Risperidone Orthostasis Warning', 'Risperidone', 'dizziness on standing', 'എഴുന്നേൽക്കുമ്പോൾ തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Tofisopam Dry Mouth Rule', 'Tofisopam', 'dry mouth', 'ഉമിനീർ കുറവ്', 'low', 'Sip water frequently; use sugar-free gum; maintain oral hygiene', 'വായ വരണ്ടുപോകുന്നത് കുറയ്ക്കാൻ വെള്ളം ഇടയ്ക്കിടെ കുടിക്കുക, പഞ്ചസാര ഇല്ലാത്ത ച്യൂയിംഗ് ഗം ഉപയോഗിക്കുക, വായ ശുചിത്വം നല്ലതായി പാലിക്കുക.', TRUE),
('Tofisopam GI Upset Rule', 'Tofisopam', 'nausea +/ stomach upset', 'ഓക്കാനം ± വയറ്റിൽ അസ്വസ്ഥത', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
