('Trihexy Confusion Alert', 'Trihexyphenidyl', 'confusion +/ forgetfulness', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ ഓർമ്മക്കുറവ്', 'high', 'Visit doctor immediately', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Trihexy Constipation Alert', 'Trihexyphenidyl', 'constipation', 'മലബന്ധം', 'medium', 'Increase fibre/fluid diet; if >3 days, Visit doctor if persistent >3 days', 'കൂടുതൽ ദ്രാവകങ്ങൾ(വെള്ളം) കുടിക്കുക, ഫൈബർ(നാരുകൾ) ഉള്ള ഭക്ഷണം കഴിക്കുക. ലക്ഷണങ്ങൾ 3 ദിവസത്തിലധികം തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Trihexy Drowsiness Rule', 'Trihexyphenidyl', 'drowsiness', 'പകൽ അമിത ഉറക്കം +/ മയക്കം.', 'low', 'Avoid driving; take at bedtime; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed, if daytime drowsiness persisting, avoid alcohol; visit doctor', 'വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. മരുന്ന് രാത്രി ഉറങ്ങാൻ പോകുന്ന സമയത്ത് കഴിക്കുക. 50 വയസ്സിന് മുകളിലുള്ളവർ കിടക്കയിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക. പകൽ മയക്കം തുടരുകയാണെങ്കിൽ മദ്യപാനം ഉണ്ടെങ്കിൽ ഒഴിവാക്കുക, ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Trihexy Dry Mouth Rule', 'Trihexyphenidyl', 'dry mouth', 'ഉമിനീർ കുറവ്', 'low', 'Sip water frequently; use sugar-free gum; maintain oral hygiene', 'വായ വരണ്ടുപോകുന്നത് കുറയ്ക്കാൻ വെള്ളം ഇടയ്ക്കിടെ കുടിക്കുക, പഞ്ചസാര ഇല്ലാത്ത ച്യൂയിംഗ് ഗം ഉപയോഗിക്കുക, വായ ശുചിത്വം നല്ലതായി പാലിക്കുക.', TRUE),
('Trihexy Dry Skin Alert', 'Trihexyphenidyl', 'dry/flushed skin', 'ചുവന്ന വരണ്ട ചർമ്മം', 'low', 'Monitor; hydrate well', 'ശരീരത്തിൽ ജലാംശം കുറയാതിരിക്കാൻ ധാരാളം വെള്ളം കുടിക്കുക.', TRUE),
('Trihexy EPS Masking Alert', 'Trihexyphenidyl', 'Dry mouth +/ blurred vision+/ constipation+/ urinary retention+/ confusion+/ memory problems+/ tachycardia+/ apparent “improvement” in stiffness or tremor +/ worsening underlying disease', 'വായ വരണ്ടത് +/കാഴ്ച മങ്ങൽ +/മലബന്ധം+/മൂത്രതടസം +/ആശയക്കുഴപ്പം +/ഓർമ്മക്കുറവ് +/ഹൃദയമിടിപ്പ് കൂടൽ +/കൈകളിലെ വിറയൽ കുറയുക +/ രോഗം കൂടുതൽ മോശമാകുക.', 'medium', 'Do not increase dose; consult doctor', 'തനിയെ ഡോസ് കൂട്ടരുത്; ഡോക്ടറുടെ ഉപദേശം തേടുക', TRUE),
('Trihexy Glaucoma Emergency', 'Trihexyphenidyl', 'severe eye pain + halos around lights', 'കഠിനമായ കണ്ണുവേദന +/ കാഴ്ച മങ്ങൽ +/ ബൾബ് / ലൈറ്റ് നോക്കുമ്പോൾ ചുറ്റും വട്ടങ്ങൾ പോലെ കാണുന്നു', 'critical', 'Go to hospital immediately; may trigger angle-closure glaucoma', 'അടിയന്തിരമായി കണ്ണ് വിഭാഗമുള്ള ആശുപത്രിയിൽ പോകുക', TRUE),
('Trihexy Hallucination Alert', 'Trihexyphenidyl', 'seeing/hearing things', 'കാണാത്ത കേൾക്കാത്ത കാര്യങ്ങൾ കാണുകയോ കേൾക്കുകയോ ചെയ്യുക (ഭ്രമങ്ങൾ)', 'high', 'Call doctor; dose reduction or discontinuation may be needed', 'ഡോക്ടറെ ബന്ധപ്പെടുക; പ്രോസൈക്ലിഡിൻ ഡോസ് കുറയ്ക്കുകയോ നിർത്തുകയോ വേണ്ടിവരാം.', TRUE),
('Trihexy Heat Intolerance Alert', 'Trihexyphenidyl', 'overheating +/ reduced sweating', 'ശരീരം അമിതമായി ചൂടാകുക ± വിയർപ്പ് കുറയുക', 'medium', 'Avoid hot environments; hydrate; call doctor if severe', 'ചൂടുള്ള ഇടങ്ങൾ ഒഴിവാക്കുക; ജലാംശം നിലനിർത്തുക (ധാരാളം വെള്ളം കുടിക്കുക); ഗുരുതരമാണെങ്കിൽ ഡോക്ടറെ വിളിക്കുക.', TRUE),
('Trihexy Tachycardia Alert', 'Trihexyphenidyl', 'palpitations +/ fast heartbeat', 'നെഞ്ചിടിപ്പ്', 'high', 'Visit doctor', 'ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Trihexy Urinary Retention Emergency', 'Trihexyphenidyl', 'difficulty urinating +/ inability to pass urine', 'മൂത്രതടസ്സം', 'critical', 'Visit doctor immediately; risk of urinary retention', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക. മൂത്രതടസ്സത്തിന്റെ സാധ്യതയുണ്ട്.', TRUE),
('Venlafaxine BP Increase Alert', 'Venlafaxine', 'high Blood pressure', 'ഉയർന്ന രക്തസമ്മർദ്ദം (BP)', 'high', 'Monitor Blood pressure; Visit doctor immediately', 'രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക; ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Venlafaxine GI Bleed Alert', 'Venlafaxine', 'easy bruising / black stools', 'നീലപ്പാടുകൾ വരുക +/കറുത്ത നിറത്തിലുള്ള മലം', 'high', 'Visit a doctor immediately to evaluate for possible bleeding (GI or otherwise), check platelet count, review drug interactions, and avoid NSAIDs.', 'രക്തസ്രാവം (ആന്തരാവയവങ്ങളിലോ മറ്റിടങ്ങളിലോ) ഉണ്ടോ എന്ന് പരിശോധിക്കാനും, പ്ലേറ്റ്‌ലെറ്റ് കൗണ്ട് പരിശോധിക്കാനും, മരുന്നുകളുടെ ഇന്ററാക്ഷൻ പരിശോധിക്കാനും, NSAID ഒഴിവാക്കാനും ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Venlafaxine Hyponatraemia Alert', 'Venlafaxine', 'confusion', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം', 'high', 'visit doctor immediately', 'ഉടൻ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Venlafaxine Insomnia Alert', 'Venlafaxine', 'insomnia', 'ഉറക്കമില്ലായ്മ', 'medium', 'Take dose early in day; if insomnia persisting, Visit doctor', 'മരുന്ന് രാവിലെ അല്ലെങ്കിൽ ദിവസം തുടങ്ങുമ്പോൾ തന്നെ കഴിക്കുക; വൈകുന്നേരം/രാത്രി ഡോസ് ഒഴിവാക്കുക; കഫീൻ (ചായ, കാപ്പി) കുറയ്ക്കുക; നല്ല ഉറക്കശീലങ്ങൾ പാലിക്കുക; ലക്ഷണങ്ങൾ കടുത്തതോ തുടർച്ചയായതോ ആണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Cariprazine Anxiety Activation', 'Cariprazine', 'restlessness/anxiety', 'പിരുപിരുപ്പ് +/ ആകുലത', 'medium', 'Visit doctor if troublesome', 'ലക്ഷണങ്ങൾ മാറാതെ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Venlafaxine Nausea Rule', 'Venlafaxine', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Lamotrigine Rash Emergency', 'Lamotrigine', 'rash +/ skin blisters', 'തൊലിയിൽ ചുവന്ന പാട്± പുണ്ണുകൾ', 'critical', 'Stop Lamotrigine immediately and go to hospital; risk of SJS/TEN', 'ലാമോട്ട്രിജിൻ ഉടൻ നിർത്തുക; ആശുപത്രിയിൽ പോകുക — SJS/TEN എന്ന ചർമ്മപ്രതികരണത്തിന്റെ അപകടസാധ്യത.', TRUE),
('Venlafaxine Sexual Dysfunction Alert', 'Venlafaxine', 'sexual dysfunction', 'ലൈംഗിക പ്രശ്നങ്ങൾ', 'medium', 'Discuss with doctor', 'ഡോക്ടറുടെ അഭിപ്രായം തേടുക', TRUE),
('Venlafaxine Tremor Alert', 'Venlafaxine', 'tremor', 'വിറയൽ', 'medium', 'Visit doctor if persistent', 'ലക്ഷണങ്ങൾ മാറാതെ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vilazodone Activation Warning', 'Vilazodone', 'inner restlessness/anxiety', 'ആകുലത / ഉത്കണ്ഠ', 'medium', 'Monitor; Visit doctor promptly if worsening', 'നിരീക്ഷിക്കുക; ആകുലതയോ അശാന്തിയോ കൂടുതലാകുന്നുവെങ്കിൽ ഉടൻ ഡോക്ടറെ ബന്ധപ്പെടുക.', TRUE),
('Vilazodone Diarrhoea Alert', 'Vilazodone', 'diarrhoea +/ abdominal cramps', 'വയറിളക്കം ± വയറുവേദന', 'medium', 'Take with food, drink adequate fluids to maintain hydration, and monitor symptoms. If symptoms are severe or persist, consult your doctor.', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക, മതിയായ ദ്രാവകങ്ങൾ കുടിച്ച് ജലാംശം നിലനിർത്തുക, ലക്ഷണങ്ങൾ നിരീക്ഷിക്കുക. ലക്ഷണങ്ങൾ കഠിനമാണെങ്കിൽ അല്ലെങ്കിൽ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vilazodone Hyponatraemia Alert', 'Vilazodone', 'confusion +/ falls in elderly', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ ബാലൻസ് നഷ്ടപ്പെടുക+/ വീഴ്ചകൾ', 'high', 'Checking sodium may be needed; Visit doctor immediately; Avoid driving; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed.', 'സോഡിയം ലെവൽ പരിശോധിക്കേണ്ടതായി വരാം. ഉടൻ ഡോക്ടറെ സമീപിക്കുക. വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക.', TRUE),
('Vilazodone Insomnia Alert', 'Vilazodone', 'reduced sleep / lack of sleep', 'ഉറക്കം കുറയുക', 'medium', 'Take dose in the morning; avoid caffeine in evening; if persistent visit doctor', 'വിലാസോഡോൺ രാവിലെ കഴിക്കുക; വൈകുന്നേരം കഫീൻ (ചായ / കാപ്പി) ഒഴിവാക്കുക; പ്രശ്നം തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vilazodone Nausea Rule', 'Vilazodone', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; common early effect; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Lorazepam Paradoxical Agitation', 'Lorazepam', 'increased agitation +/ irritability', 'പിരുപിരുപ്പ്+/ ക്ഷോഭം', 'high', 'Stop Lorazepam under medical advice; Visit doctor', 'മെഡിക്കൽ നിർദേശപ്രകാരം ലോറാസിപാം നിർത്തുക; ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vilazodone Sexual Dysfunction Alert', 'Vilazodone', 'sexual side effects', 'ലൈംഗിക പ്രശ്നങ്ങൾ', 'medium', 'Discuss with doctor; consider dose or drug change', 'ഡോക്ടറുടെ അഭിപ്രായം തേടുക', TRUE),
('Vilazodone Suicidal Thought Alert', 'Vilazodone', 'suicidal thoughts', 'ആത്മഹത്യാ ചിന്തകൾ', 'critical', 'Urgent psychiatric help or hospital assessment, do not stay alone', 'ഇത്തരം ചിന്തകൾ ഉണ്ടെങ്കിൽ ഉടൻ ഡോക്ടറെ കാണുക / അടുത്ത ആശുപത്രിയിൽ പോകുക. സഹായം തേടുന്നത് വളരെ പ്രധാനമാണ്. തനിച്ചിരിക്കുക ഒഴിവാക്കണം', TRUE),
('Trazodone Orthostasis Warning', 'Trazodone', 'dizziness on standing', 'എഴുന്നേൽക്കുമ്പോൾ തലകറക്കം', 'medium', 'Stand up slowly, stay well hydrated, sit or lie down if dizzy, avoid driving, monitor blood pressure, and consult your doctor if symptoms are frequent, persistent, or associated with falls.', 'പതുക്കെ എഴുന്നേൽക്കുക, ആവശ്യത്തിന് വെള്ളം കുടിച്ച് ശരീരത്തിലെ ജലാംശം നിലനിർത്തുക, തലചുറ്റൽ തോന്നിയാൽ ഇരിക്കുകയോ കിടക്കുകയോ ചെയ്യുക, വാഹനമോടിക്കുന്നത് ഒഴിവാക്കുക, രക്തസമ്മർദ്ദം നിരീക്ഷിക്കുക, ലക്ഷണങ്ങൾ പതിവായി ഉണ്ടാകുകയോ മാറാതെ തുടരുകയോ വീഴ്ചകളോടൊപ്പം ഉണ്ടാകുകയോ ചെയ്താൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vortioxetine GI Upset Rule', 'Vortioxetine', 'diarrhoea +/ abdominal cramps', 'വയറിളക്കം ± വയറുവേദന', 'low', 'Take with food, drink adequate fluids to maintain hydration, and monitor symptoms. If symptoms are severe or persist, consult your doctor.', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക, മതിയായ ദ്രാവകങ്ങൾ കുടിച്ച് ജലാംശം നിലനിർത്തുക, ലക്ഷണങ്ങൾ നിരീക്ഷിക്കുക. ലക്ഷണങ്ങൾ കഠിനമാണെങ്കിൽ അല്ലെങ്കിൽ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
('Vortioxetine Headache Rule', 'Vortioxetine', 'headache', 'തലവേദന', 'low', 'Monitor; simple analgesic if needed; Visit doctor if persistent; ensure adequate water intake', 'കൂടുതൽ വെള്ളം കുടിക്കുക; ആവശ്യമായാൽ ലളിതമായ വേദനാശമന മരുന്ന് (പാരാസിറ്റമോൾ) കഴിക്കാൻ പരിഗണിക്കുക; തുടർന്നും ഗുരുതരവുമെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക', TRUE),
('Vortioxetine Hyponatraemia Alert', 'Vortioxetine', 'confusion +/ unsteadiness', 'അവ്യക്തത+/ ആശയക്കുഴപ്പം+/ ബാലൻസ് നഷ്ടപ്പെടുക+/ വീഴ്ചകൾ', 'high', 'Checking sodium may be needed; Visit doctor immediately; Avoid driving; take precautions to avoid fall if you are above 50 years of age especially when getting up from bed.', 'സോഡിയം ലെവൽ പരിശോധിക്കേണ്ടതായി വരാം. ഉടൻ ഡോക്ടറെ സമീപിക്കുക. വാഹനം ഓടിക്കുകയോ ഭാരമേറിയ യന്ത്രങ്ങൾ ഉപയോഗിക്കുകയോ ചെയ്യരുത്. വീഴ്ച ഒഴിവാക്കാൻ പ്രത്യേക മുൻകരുതലുകൾ പാലിക്കുക.', TRUE),
('Vortioxetine Nausea Rule', 'Vortioxetine', 'nausea', 'ഓക്കാനം', 'low', 'Take with food; common early effect; usually settles; Inform doctor if persistent', 'ഭക്ഷണത്തോടൊപ്പം കഴിക്കുക; തുടക്കത്തിൽ സാധാരണയായി ഉണ്ടാകുന്ന പാർശ്വഫലമാണ്; സാധാരണയായി സ്വയം കുറയും; തുടർന്നുനിൽക്കുകയാണെങ്കിൽ ഡോക്ടറെ അറിയിക്കുക.', TRUE),
('Escitalopram Activation Warning', 'Escitalopram', 'restlessness/anxiety', 'പിരുപിരുപ്പ് +/ ആകുലത', 'medium', 'Visit doctor if symptom persist for more than 3 days', 'ലക്ഷണങ്ങൾ മാറാതെ തുടരുകയാണെങ്കിൽ ഡോക്ടറെ സമീപിക്കുക.', TRUE),
